//! The YAML writer against PyYAML 6.0.3: the three emitter profiles, the
//! markdown framing and the YAML-neuron block, byte for byte.
//!
//! The rows are generated by `parity/tools/yaml_emit_expectations.py`, which
//! runs the code v2 runs in the oracle venv:
//!
//!     parity/.oracle/venv/bin/python -I parity/tools/yaml_emit_expectations.py --write

use kluris_core::frontmatter::{LineEnding, write_markdown, write_yaml_neuron};
use kluris_core::yaml::{Date, DateTime, Map, Profile, Value, emit};
use num_bigint::BigInt;

fn s(text: &str) -> Value {
    Value::Str(text.to_string())
}

fn i(digits: &str) -> Value {
    Value::Int(digits.parse::<BigInt>().unwrap())
}

fn f(repr: &str) -> Value {
    Value::Float(repr.parse::<f64>().unwrap())
}

fn b(v: bool) -> Value {
    Value::Bool(v)
}

fn n() -> Value {
    Value::Null
}

fn d(y: u32, m: u32, day: u32) -> Value {
    Value::Date(Date::new(y, m, day).unwrap())
}

#[allow(clippy::too_many_arguments)]
fn dt(y: u32, mo: u32, day: u32, h: u32, mi: u32, sec: u32, us: u32, off: Option<i32>) -> Value {
    let date = Date::new(y, mo, day).unwrap();
    Value::DateTime(DateTime::new(date, h, mi, sec, us, off).unwrap())
}

fn sq(items: Vec<Value>) -> Value {
    Value::Seq(items)
}

fn m(entries: Vec<(&str, Value)>) -> Map {
    entries
        .into_iter()
        .map(|(k, v)| (k.to_string(), v))
        .collect()
}

fn mp(entries: Vec<(&str, Value)>) -> Value {
    Value::Map(m(entries))
}

struct Row {
    name: &'static str,
    meta: Map,
    md: &'static str,
    yml: &'static str,
    config: &'static str,
}

fn row(
    name: &'static str,
    meta: Vec<(&str, Value)>,
    md: &'static str,
    yml: &'static str,
    config: &'static str,
) -> Row {
    Row {
        name,
        meta: m(meta),
        md,
        yml,
        config,
    }
}

struct MarkdownRow {
    name: &'static str,
    meta: Map,
    body: &'static str,
    line_ending: LineEnding,
    expected: &'static str,
}

fn md_row(
    name: &'static str,
    meta: Vec<(&str, Value)>,
    body: &'static str,
    line_ending: LineEnding,
    expected: &'static str,
) -> MarkdownRow {
    MarkdownRow {
        name,
        meta: m(meta),
        body,
        line_ending,
        expected,
    }
}

struct NeuronRow {
    name: &'static str,
    meta: Map,
    body: &'static str,
    expected: &'static str,
}

fn neuron_row(
    name: &'static str,
    meta: Vec<(&str, Value)>,
    body: &'static str,
    expected: &'static str,
) -> NeuronRow {
    NeuronRow {
        name,
        meta: m(meta),
        body,
        expected,
    }
}

/// Every mismatch, not just the first, so one run shows the whole picture.
fn check_profiles(rows: Vec<Row>) {
    let mut failures = Vec::new();
    let total = rows.len() * 3;
    for row in &rows {
        for (profile, expected) in [
            (Profile::Md, row.md),
            (Profile::Yml, row.yml),
            (Profile::Config, row.config),
        ] {
            let got = emit(&row.meta, profile);
            if got != expected {
                failures.push(format!(
                    "{} [{profile:?}]\n  expected: {expected:?}\n  got:      {got:?}",
                    row.name
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {total} outputs differ from PyYAML:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn scalars_match_pyyaml_in_every_profile() {
    check_profiles(scalar_rows());
}

#[test]
fn documents_match_pyyaml_in_every_profile() {
    check_profiles(document_rows());
}

#[test]
fn markdown_framing_matches_python_frontmatter() {
    let rows = markdown_rows();
    let total = rows.len();
    let failures: Vec<String> = rows
        .into_iter()
        .filter_map(|row| {
            let got = write_markdown(&row.meta, row.body, row.line_ending);
            (got != row.expected).then(|| {
                format!(
                    "{}\n  expected: {:?}\n  got:      {got:?}",
                    row.name, row.expected
                )
            })
        })
        .collect();
    assert!(
        failures.is_empty(),
        "{} of {total} markdown files differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn yaml_neuron_block_matches_v2() {
    let rows = yaml_neuron_rows();
    let total = rows.len();
    let failures: Vec<String> = rows
        .into_iter()
        .filter_map(|row| {
            let got = write_yaml_neuron(&row.meta, row.body);
            (got != row.expected).then(|| {
                format!(
                    "{}\n  expected: {:?}\n  got:      {got:?}",
                    row.name, row.expected
                )
            })
        })
        .collect();
    assert!(
        failures.is_empty(),
        "{} of {total} YAML neurons differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn written_frontmatter_reads_back() {
    let meta = m(vec![
        ("title", s("\u{1F680} Caf\u{e9}: a #title")),
        ("created", d(2026, 1, 2)),
        (
            "tags",
            sq(vec![
                s("yes"),
                b(true),
                i("1000000000000000000000000000000"),
            ]),
        ),
        ("nested", mp(vec![("z", f("-0.0")), ("a", sq(vec![]))])),
    ]);
    let markdown = write_markdown(&meta, "    indented\nbody\n", LineEnding::Crlf);
    let read = kluris_core::frontmatter::parse(&markdown).unwrap();
    let sorted: Map = {
        let mut entries: Vec<_> = meta.clone().into_iter().collect();
        entries.sort_by(|a, b| a.0.cmp(&b.0));
        let mut map: Map = entries.into_iter().collect();
        if let Some(Value::Map(nested)) = map.get_mut("nested") {
            nested.sort_keys();
        }
        map
    };
    assert_eq!(read.meta, sorted);
    // The reader keeps everything after the closing line, the blank one too.
    assert_eq!(read.body, "\r\n    indented\r\nbody\r\n");
    assert_eq!(read.line_ending, LineEnding::Crlf);

    let neuron = write_yaml_neuron(&meta, "x: 1\r\n");
    let read = kluris_core::frontmatter::parse_yaml_neuron(&neuron).unwrap();
    assert_eq!(read.meta, sorted);
    assert_eq!(read.body, "x: 1\r\n");
}

